SELECT * FROM customer_shopping LIMIT 100;

-- total revenue generated by different gender
Select gender, SUM(purchase_amount) as revenue from customer_shopping
group by gender;

--which customer use discount but also spend money more 
--than avg purchase amount
Select customer_id, purchase_amount from customer_shopping
where discount_applied ='Yes' and 
purchase_amount >=(Select Avg(purchase_amount) from customer_shopping);
